void swap_int(int *a, int *b) {
    if (a == NULL || b == NULL) return;
    int tmp = *a;
    *a = *b;
    *b = tmp;
}

int values[] = {10, 20, 30};
for (size_t i = 0; i < 3; ++i) {
    printf("%d\n", *(values + i));
}
